    "desc": "我们设计了一款圆形刷子，让您从各个角度都能充分感受到优质山羊毛的硬度和柔和触感。 这款毛笔融合了书法技巧，完全手工制作，所有没有尖端的刷毛都被去除，所以用起来一点也不扎手。 手柄采用天然木材制成，设计奢华，木纹清晰可见。 ■ 散粉刷 由于刷毛浓密且富有弹性，因此各个面都可以使用，轻松打造光泽效果。 它的圆形设计使其可以360度全方位使用，而且这种刷子可以轻松调整涂抹量，而不会涂抹过多的颜料。 ■ 腮红刷 这款刷子能很好地抓粉，显色度极佳，让您可以随心所欲地涂抹和晕染腮红。 ■ 眼影刷 L 使用像书法笔一样形状保持性好的画笔，你可以将眼影精确地涂抹在你想要的位置，例如眼睑上，并打造出自然的渐变效果。 ■ 眼影刷 M 使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。 ■唇线刷 使用像书法笔一样能保持形状的画笔，您可以随心所欲地画出眼线和唇线。",
    "detail": "仅使用优质山羊毛和 Hokohoho 的最高品质Yoshiki系列。 我们设计了一款圆形刷子，让您从各个角度都能充分感受到优质山羊毛的硬度和柔和触感。 这款毛笔融合了书法技巧，完全手工制作，所有没有尖端的刷毛都被去除，所以用起来一点也不扎手。 手柄采用天然木材制成，设计奢华，木纹清晰可见。 ■ 散粉刷 由于刷毛浓密且富有弹性，因此各个面都可以使用，轻松打造光泽效果。 它的圆形设计使其可以360度全方位使用，而且这种刷子可以轻松调整涂抹量，而不会涂抹过多的颜料。 ■ 腮红刷 这款刷子能很好地抓粉，显色度极佳，让您可以随心所欲地涂抹和晕染腮红。 ■ 眼影刷 L 使用像书法笔一样形状保持性好的画笔，你可以将眼影精确地涂抹在你想要的位置，例如眼睑上，并打造出自然的渐变效果。 ■ 眼影刷 M 使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。 ■唇线刷 使用像书法笔一样能保持形状的画笔，您可以随心所欲地画出眼线和唇线。 構 成 ■ [KY-1] 粉刷 形状：丸 出穂：36ｍｍ 全長：151ｍｍ ■ [KY-2] 腮红刷 形状：丸 出穂：30ｍｍ 全長：145ｍｍ ■ 【KY-3】眼影刷 L 形状：丸 出穂：14ｍｍ 全長：139ｍｍ ■ 【KY-4】眼影刷 M 形状：丸 出穂：10ｍｍ 全長：135ｍｍ ■ [KY-5]唇眼线刷 形状：丸 出穂：8ｍｍ 全長：133ｍｍ 毛毛质量：优质细羊毛 黑色皮革小袋",
    "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>仅使用优质山羊毛和 Hokohoho 的最高品质Yoshiki系列。</strong></span></p>\r\n\r\n<p>我们设计了一款圆形刷子，让您从各个角度都能充分感受到优质山羊毛的硬度和柔和触感。<br>这款毛笔融合了书法技巧，完全手工制作，所有没有尖端的刷毛都被去除，所以用起来一点也不扎手。</p>\r\n\r\n<p>手柄采用天然木材制成，设计奢华，木纹清晰可见。<br>\r\n&nbsp;</p>\r\n\r\n<p><strong>■ 散粉刷</strong><br>由于刷毛浓密且富有弹性，因此各个面都可以使用，轻松打造光泽效果。<br>它的圆形设计使其可以360度全方位使用，而且这种刷子可以轻松调整涂抹量，而不会涂抹过多的颜料。<br>\r\n<strong>■ 腮红刷</strong><br>这款刷子能很好地抓粉，显色度极佳，让您可以随心所欲地涂抹和晕染腮红。<br>\r\n<strong>■ 眼影刷 L</strong><br>使用像书法笔一样形状保持性好的画笔，你可以将眼影精确地涂抹在你想要的位置，例如眼睑上，并打造出自然的渐变效果。<br>\r\n<strong>■ 眼影刷 M</strong><br>使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。<br>\r\n<strong>■唇线刷</strong><br>使用像书法笔一样能保持形状的画笔，您可以随心所欲地画出眼线和唇线。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>構　成</th>\r\n<td>\r\n<p>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000326\" target=\"_black\">[KY-1] 粉刷</a><br>形状：丸　出穂：36ｍｍ　全長：151ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000327\" target=\"_black\">[KY-2] 腮红刷</a><br>形状：丸　出穂：30ｍｍ　全長：145ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000328\" target=\"_black\">【KY-3】眼影刷 L</a><br>形状：丸　出穂：14ｍｍ　全長：139ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000329\" target=\"_black\">【KY-4】眼影刷 M</a><br>形状：丸　出穂：10ｍｍ　全長：135ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000330\" target=\"_black\">[KY-5]唇眼线刷</a><br>形状：丸　出穂：8ｍｍ　全長：133ｍｍ<br>毛发质量：优质细羊毛<br>黑色皮革小袋</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>",
