    "desc": "榻榻米衬布是指附着在榻榻米垫边缘以起到加固和装饰作用的布料。 如今，由于设计种类繁多，它不仅常用于榻榻米垫，还常被用作小型工艺品的材料。 这款手拿包采用传统的日式榻榻米包边工艺，既散发着怀旧气息，又不失清新现代感。它还附赠一套方便日常使用的腮红和唇膏。 随附的腮红刷采用高级粗山羊毛，这是一种优质山羊毛，因此刷头纤细，触感极佳。 这款唇刷采用一种新型材料制成，独特地结合了合成纤维和鼬纤维，从而达到恰到好处的弹性，让您能够在各种唇形上描绘出精准的线条。 这套豪华套装，配有桐木盒，是馈赠佳品。 您可以从四种类型的袋子中进行选择。 ・市松 ・红梅 ・黑梅",
