    "desc": "我们设计了一款圆形刷子，让您从各个角度都能充分感受到优质山羊毛的硬度和柔和触感。 这款毛笔融合了书法技巧，完全手工制作，所有没有尖端的刷毛都被去除，所以用起来一点也不扎手。 由于刷毛浓密且富有弹性，各个面都可以使用，因此很容易增加光泽。 这款刷子既可以搭配粉状粉底使用，也可以搭配粉底液使用，而且易于涂抹，不会造成厚重、卡粉的妆感。 手柄采用天然木材制成，设计奢华，木纹清晰可见。",
