    "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>KOYUDO collection的最高峰系列诞生。</strong></span></p>\r\n\r\n<p><strong>通过将优质山羊毛与精心挑选的灰色松鼠毛混合，并添加源自晃祐堂毛笔制造技术的“移动技术”，我们创造了一种柔软且具有恰到好处的弹性的毛笔。独特的化妆刷诞生了。</strong></p>\r\n\r\n<p>　</p>\r\n\r\n<p>使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。<br>\r\n<br>这款毛笔融合了书法技法，由技艺精湛的工匠精心手工制作，每一支都是独一无二的。<br>有些天然毛发天生就没有毛尖或者比较粗硬，所以需要用眼睛和指尖的触觉来去除。<br>这个过程制造出的化妆刷不会让皮肤感到刺痛，对皮肤也很温和。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>\r\n<p>丸平</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>灰松鼠毛/山羊毛</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>\r\n<p>15mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>110mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>",
