    "desc": "通过将优质山羊毛与精心挑选的灰色松鼠毛混合，并添加源自晃祐堂毛笔制造技术的“移动技术”，我们创造了一种柔软且具有恰到好处的弹性的毛笔。独特的化妆刷诞生了。 ■ 散粉刷 这款画笔拥有非常大、圆润扁平的刷头，刷毛浓密且富有弹性，能够轻松打造光泽亮丽的涂装效果。它是一款易于控制的画笔，不会涂抹过多的颜料。 ■ 散粉腮红刷 这款刷子不仅可以作为散粉刷打造理想的光泽，还可以作为腮红刷使用，兼具粉末吸附性和显色性，让您能够随心所欲地涂抹和晕染腮红。 ■ 眼影刷 L 使用像书法笔一样形状保持性好的画笔，你可以将眼影精确地涂抹在你想要的位置，例如眼睑上，并打造出自然的渐变效果。 ■ 眼影刷 M 使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。 ■ 抛光刷 这款独特的扇形大刷子可轻柔地去除皮肤表面的多余粉末，打造美丽透亮的肤色。 它也非常适合在全脸和颈部涂抹一层薄薄的定妆粉。 这款毛笔融合了书法技法，由技艺精湛的工匠精心手工制作，每一支都是独一无二的。 天然刷毛有时会出现缺毛或毛质粗糙的情况，我们会用眼睛和指尖去除这些毛。这样处理后的化妆刷触感温和，不会刺激皮肤。",
