    "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>KOYUDO collection的最高峰系列诞生。</strong></span></p>\r\n\r\n<p><strong>通过将优质山羊毛与精心挑选的灰色松鼠毛混合，并添加源自晃祐堂毛笔制造技术的“移动技术”，我们创造了一种柔软且具有恰到好处的弹性的毛笔。独特的化妆刷诞生了。</strong></p>\r\n\r\n<p>　</p>\r\n\r\n<p><strong>■ 散粉刷</strong><br>这款画笔拥有非常大、圆润扁平的刷头，刷毛浓密且富有弹性，能够轻松打造光泽亮丽的涂装效果。它是一款易于控制的画笔，不会涂抹过多的颜料。<br>\r\n<strong>■ 散粉腮红刷</strong><br>这款刷子不仅可以作为散粉刷打造理想的光泽，还可以作为腮红刷使用，兼具粉末吸附性和显色性，让您能够随心所欲地涂抹和晕染腮红。<br>\r\n<strong>■ 眼影刷 L</strong><br>使用像书法笔一样形状保持性好的画笔，你可以将眼影精确地涂抹在你想要的位置，例如眼睑上，并打造出自然的渐变效果。<br>\r\n<strong>■ 眼影刷 M</strong><br>使用像书法笔一样能保持形状的画笔，您可以精准地在眼睑上添加您想要的重点妆容。<br>\r\n<strong>■ 抛光刷</strong><br>这款独特的扇形大刷子可轻柔地去除皮肤表面的多余粉末，打造美丽透亮的肤色。<br>它也非常适合在全脸和颈部涂抹一层薄薄的定妆粉。<br>\r\n<br>这款毛笔融合了书法技法，由技艺精湛的工匠精心手工制作，每一支都是独一无二的。<br>天然刷毛有时会出现缺毛或毛质粗糙的情况，我们会用眼睛和指尖去除这些毛。这样处理后的化妆刷触感温和，不会刺激皮肤。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>構　成</th>\r\n<td>\r\n<p>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000338\" target=\"_blank\">【P-1】散粉刷</a><br>形状：丸平　出穂：50ｍｍ　全長：128ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000339\" target=\"_blank\">【P-2】散粉腮红刷</a><br>形状：丸平　出穂：40ｍｍ　全長：118ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000340\" target=\"_blank\">【P-3】眼影刷 L</a><br>形状：丸平　出穂：20ｍｍ　全長：115ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000341\" target=\"_blank\">【P-4】眼影刷 M</a><br>形状：丸平　出穂：15ｍｍ　全長：110ｍｍ<br>■<a href=\"http://www.koyudo.co.jp/shopdetail/000000000342\" target=\"_blank\">[P-5] 抛光刷</a><br>形状：丸平　出穂：30ｍｍ　全長：125ｍｍ<br>毛发类型：灰松鼠毛和山羊毛<br>附赠化妆盒和化妆袋。</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>",
