    "desc": "由于采用了最柔软的山羊毛品种“Saibikoho”，因此其毛发具有普通山羊毛所不具备的光滑质地和光泽。 晃祐堂的化妆刷采用独特的工艺制作，融合了书法毛笔的制作方法。 这款粉刷刷头直径为Φ30mm，是目前市面上最大的粉刷尺寸。它采用高密度、高品质山羊毛制成，触感柔软舒适，让您尽享上妆乐趣。 柄部采用樱桃木制成，莳绘（漆器上涂有金粉或银粉）的樱花图案给人一种奢华的感觉。 ● 枝头樱花 ● *请注意，您的订单可能需要一些时间才能发货。我们可能无法在您指定的日期和时间送达。 大下正一郎 在本地产业推广Makie展览会上连续获奖 他致力于研究莳绘（金漆）技艺，追求古代传统莳绘和现代莳绘，将传统精神与新技术相结合，探索山中漆器的未来。",
    "detail": "补货了！ ！ 由制笔大师植松藤森制作的顶级熊野筆 一款与莳绘（日本漆器）工艺相结合的顶级产品现已限量发售。 由于采用了最柔软的山羊毛品种“Saibikoho”，因此其毛发具有普通山羊毛所不具备的光滑质地和光泽。 晃祐堂的化妆刷采用独特的工艺制作，融合了书法毛笔的制作方法。 这款粉刷刷头直径为Φ30mm，是目前市面上最大的粉刷尺寸。它采用高密度、高品质山羊毛制成，触感柔软舒适，让您尽享上妆乐趣。 柄部采用樱桃木制成，莳绘（漆器上涂有金粉或银粉）的樱花图案给人一种奢华的感觉。 您可以从樱花图案中选择。 ● 枝头樱花 ● 散らし桜（Scattered cherry Blossoms）Sold out 即使您继续完成购买，我们也会取消订单。 *请注意，您的订单可能需要一些时间才能发货。我们可能无法在您指定的日期和时间送达。 莳绘艺术家简介 大下正一郎 在本地产业推广Makie展览会上连续获奖 他致力于研究莳绘（金漆）技艺，追求古代传统莳绘和现代莳绘，将传统精神与新技术相结合，探索山中漆器的未来。 形状 圆圈 毛质 山羊毛 細微光峰 毛长 45mm 全长 125mm",
    "detailHtml": "<p><span style=\"color: rgb(204, 0, 153);\"><strong>　<span style=\"font-size: 16px;\">补货了！ ！</span></strong></span><br>\r\n<span style=\"color: rgb(255, 0, 0);\"><strong>由制笔大师植松藤森制作的顶级熊野筆<br>一款与莳绘（日本漆器）工艺相结合的顶级产品现已限量发售。</strong></span><br>\r\n&nbsp;</p>\r\n\r\n<p>　<br>由于采用了最柔软的山羊毛品种“Saibikoho”，因此其毛发具有普通山羊毛所不具备的光滑质地和光泽。<br>晃祐堂的化妆刷采用独特的工艺制作，融合了书法毛笔的制作方法。</p>\r\n\r\n<p>　</p>\r\n\r\n<p>这款粉刷刷头直径为Φ30mm，是目前市面上最大的粉刷尺寸。它采用高密度、高品质山羊毛制成，触感柔软舒适，让您尽享上妆乐趣。<br>柄部采用樱桃木制成，莳绘（漆器上涂有金粉或银粉）的樱花图案给人一种奢华的感觉。</p>\r\n\r\n<p>　</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\">您可以从樱花图案中选择。</span><br>● 枝头樱花<br>●<span style=\"color:#ff0000;\"><strong>散らし桜（Scattered cherry Blossoms）Sold　out<br>即使您继续完成购买，我们也会取消订单。</strong></span><br>*请注意，您的订单可能需要一些时间才能发货。我们可能无法在您指定的日期和时间送达。</p>\r\n\r\n<p>　</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\">莳绘艺术家简介</span><br>\r\n<strong>大下正一郎</strong><br>在本地产业推广Makie展览会上连续获奖<br>他致力于研究莳绘（金漆）技艺，追求古代传统莳绘和现代莳绘，将传统精神与新技术相结合，探索山中漆器的未来。</p>\r\n\r\n<p>　</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>形状</th>\r\n<td>圆圈</td>\r\n</tr>\r\n<tr>\r\n<th>毛质</th>\r\n<td>\r\n<p>山羊毛　細微光峰</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>毛长</th>\r\n<td>\r\n<p>45mm</p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<th>全长</th>\r\n<td>\r\n<p>125mm</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>",
