    "desc": "这款沙比基钓线采用极其柔软、精细打磨的山羊毛制成，线头用柿子单宁染色，营造出一种令人怀旧的暮色色彩。 [柿单宁染料] 柿单宁是一种完全天然的染料，自平安时代以来一直被不断传承，它具有抗菌特性，并被用于各种日常场合。 它的魅力之一在于，随着时间的推移，颜色会渗透到织物中，变得越来越深，越来越浓郁。 *由于这是一种天然染料，洗涤过程中可能会褪色。 享受使用次数越多，质地发生变化的感觉。 *由于采用手工染色工艺，实际产品颜色可能与图片有所不同。 刷头采用优质山羊毛制成。其柔软圆润的形状使其成为市面上蓬松度较高的散粉刷之一。 粉末可以轻柔均匀地涂抹在皮肤上。 手柄采用天然木材制成，设计奢华，木纹清晰可见。",
