    "desc": "我们开发这款产品，是希望熊野筆这种与高端化妆刷紧密相关的刷子，能够被用于更广泛的日常用途。 一种用途广泛的椭圆形毛绒玩具，由山羊毛和合成纤维混合制成。 ● 用于清洁电脑、智能手机和平板电脑屏幕 ● 用于抛光皮鞋和皮革制品 ● 用于清洁窗框等狭小缝隙。 它采用天然木材制成，其时尚的设计使其成为任何室内装饰的点睛之笔。 这款产品外形可爱又实用，是送礼佳品。 我们使用的礼盒是用回收的折纸鹤制成的，这些折纸鹤是从世界各地收集来的，作为对和平的祈祷，并放置在广岛和平纪念公园的纪念塔上。 【使用方法演示视频】 https://www.youtube.com/watch?v=W3ALMGfQ-e0 [玻璃珠] https://www.youtube.com/watch?v=I1v9U3rMzM8&t=11s [擦鞋版] https://www.youtube.com/watch?v=NwU_3xum-Dw [配件] https://www.youtube.com/watch?v=hYkQkUsdg6I&t=11s 尺寸： 绒毛长度 20 mm / 65 mm（长） × 48 mm（宽） × 40 mm（高） 材 質： 山羊毛/合成纤维/橡木",
