    "desc": "洗脸刷～世界三大美女～ 裕人礫翔×植松義貴 コラボレーション 乐胜弘人是日本顶尖的花式剑艺术家之一。 植松义孝是日本顶尖的画笔制造商之一，公司位于广岛县熊野町。此次双方合作推出了一款独特的限量版产品。 世界知名的箔片艺术家雷城祐斗出生于京都西阵的一个箔片工艺世家，是一位拥有无与伦比的天赋和技艺的独一无二的箔片艺术家。 植松嘉孝18岁便投身书法，并毕生致力于此。年少时，他仿制了正仓院宝库中珍藏的天针毛笔，成为日本顶尖的制笔大师之一。两人在艺术审美和工艺价值的理念上不谋而合，决定携手合作，并立即着手制作原型。 这是箔片与画笔的完美结合。箔片和画笔都力求完美，画笔的颜色、触感和使用体验也同样如此。他们反复讨论、制作原型，最终打造出这款臻品。 这100支限量版化妆刷均为独立制作，每一支都拥有独一无二的设计，绝无雷同。当你拿起其中一支，感受每支化妆刷独特的魅力时，一段全新的故事便由此展开。 我们希望您能充分享受这两位技艺精湛的工匠所创造的独特世界。 小野小町是日本历史上最著名的诗人之一，生活在平安时代。 我以黑白两色展现了小町的书法技巧和外貌，突出了她的书法天赋。 包裹毛笔的風呂敷（包布）由 100% 纯蚕丝绉纱制成。 这种面料是風呂敷（包袱布）的典型代表，是日本独有的纺织品，在海外并不常见。其纬线经过强力捻合，由此产生的解捻力造就了“绉”的纹理。纯真丝绉布光泽适中，质地柔软饱满，是日本引以为傲的高品质面料。 本产品配有刷子和类似和服的風呂敷（包袱布），穿戴时右侧覆盖左侧（布料右侧先接触皮肤）。我们希望您能像珍惜生命中的每一天一样，珍爱它，让它陪伴您多年。 （请勿清洗風呂敷。） ●关于箔（金属零件、轴部） ・请勿用冷水或热水清洗。请勿长时间处于潮湿状态。 - 请注意不要将其暴露于高温、阳光直射或使用稀释剂、汽油等，否则可能会导致变色或变形。 ・如果长时间放置在高温或潮湿的地方，可能会导致发霉或金属生锈，因此请存放在低温、低湿、通风良好的地方。 - 由于是手工制作，颜色和形状可能与照片有所不同。 ・本产品由天然木材制成，上面粘有真金箔。使用产品时，箔片会因摩擦而逐渐剥落。感谢您的理解。 ・由于本产品的特性，制作精细，请勿用力过猛。施加强力可能会造成损坏。从高处跌落或用尖锐物体强力接触可能会导致刮伤或剥落。 ・本产品使用金属。如果您对金属过敏，请避免使用。 此外，本产品的制造根据用途考虑了用途和功能。请避免将其用于预期目的以外的任何目的。",
