    "detailHtml": "<p><span style=\"color: rgb(255, 0, 0);\"><strong>KOYUDO collection中最高峰系列</strong></span></p>\n\n<p><strong>我们将精心挑选的优质山羊毛与晃祐堂在书法笔制造方面积累的专业知识所开发的独特“移色技术”相结合，创造出一种与众不同的化妆刷，它既柔软又具有恰到好处的弹性。<br>\n　</strong><br>这款刷子不仅可以作为散粉刷打造理想的光泽，还可以作为腮红刷使用，兼具粉末吸附性和显色性，让您能够随心所欲地涂抹和晕染腮红。<br>\n<br>这款毛笔融合了书法技法，由技艺精湛的工匠精心手工制作，每一支都是独一无二的。<br>有些天然毛发天生就没有毛尖或者比较粗硬，所以需要用眼睛和指尖的触觉来去除。<br>这个过程制造出的化妆刷不会让皮肤感到刺痛，对皮肤也很温和。</p>\n<p style=\"text-align: center;\"><br>\n&nbsp;</p>\n\n<table class=\"sstable\">\n<tbody>\n<tr>\n<th>形状</th>\n<td>丸平</td>\n</tr>\n<tr>\n<th>毛质</th>\n<td>高品质细光峰/黑色粗光峰</td>\n</tr>\n<tr>\n<th>毛长</th>\n<td>40mm</td>\n</tr>\n<tr>\n<th>全长</th>\n<td>118mm</td>\n</tr>\n</tbody>\n</table>",
