    "desc": "KOYUDO collectionにおける最高峰のシリーズ 厳選した上質細光峰に山羊毛を混ぜ込み、そこに晃祐堂の書筆製造のノウハウから生まれた“ずらす技術”を加えることで、柔らかさの中にも適度な弾力がある、今までにない化粧筆が生まれました。 書筆のようにまとまりの良いブラシで、アイホールなど思い通りのポイントにアイシャドウを入れ自然にグラデーションをつけることができます。 書筆の技術を取り入れたこのブラシは、職人が1本1本丁寧に手作りで生産しております。 天然毛の中にもともと毛先が無いものや粗いものがあるため、それを目と指先の感覚などで取り除いていきます。 そうすることでチクチクした感じがない、肌当たりの良い化粧筆を作っています。",
