    "desc": "母女情深。幸福的魔法降临的那一刻。 母亲完成了婚礼的准备工作。 使用享誉全球的熊野筆，为新娘举行“涂红仪式”，祈求幸福美满。为了这一象征着对新娘美好祝愿的仪式，Koyudo 特别准备了一套腮红刷和唇刷。 → [WRP002] 附加包装",
    "detail": "母女情深。幸福的魔法降临的那一刻。 母亲完成了婚礼的准备工作。 使用享誉全球的熊野筆，为新娘举行“涂红仪式”，祈求幸福美满。为了这一象征着对新娘美好祝愿的仪式，Koyudo 特别准备了一套腮红刷和唇刷。 *包括仅限在线丝带包装 構 成 ■チークブラシ 毛質：山羊毛 形状：丸平 出穂：35mm 全長：155mm ■リップブラシ 毛質：PBT/イタチ 形状：尖り 出穂：11mm 全長：141mm ■箱 ： おりづる再生ギフト箱 *如果您需要礼品包装纸或礼品标签， [WRP002] 请将此商品与额外的礼品包装一起购买。 → [WRP002] 附加包装",
    "detailHtml": "<p>母女情深。幸福的魔法降临的那一刻。<br>母亲完成了婚礼的准备工作。<br>使用享誉全球的熊野筆，为新娘举行“涂红仪式”，祈求幸福美满。为了这一象征着对新娘美好祝愿的仪式，Koyudo 特别准备了一套腮红刷和唇刷。</p>\r\n\r\n<p><span style=\"color: rgb(255, 0, 0);\"><strong>*包括仅限在线丝带包装</strong></span><br>\r\n&nbsp;</p>\r\n\r\n<table class=\"sstable\">\r\n<tbody>\r\n<tr>\r\n<th>構　成</th>\r\n<td>\r\n<p>■チークブラシ　毛質：山羊毛<br>形状：丸平　出穂：35mm　全長：155mm<br>■リップブラシ　毛質：PBT/イタチ<br>形状：尖り　出穂：11mm　全長：141mm<br>■箱　：　おりづる再生ギフト箱</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n\r\n<div style=\"text-align: left;\"><br>\r\n<strong><span style=\"color: red;\">*如果您需要礼品包装纸或礼品标签，<br>[WRP002] 请将此商品与额外的礼品包装一起购买。</span><br>\r\n<a href=\"./000000000151/\">→ [WRP002] 附加包装</a></strong></div>",
