    "desc": "Yoshiki Tenpyo五件套 (YT-S-5) 是打造完美妆容的必备单品。这款化妆刷套装采用优质细密针织刷头精心打造，彰显了熊野筆的精湛工艺。刷头触感顺滑，打造专业妆容。尺寸适中，无论是居家还是外出，都非常适合使用。 每把刷子都拥有不同的刷毛和形状，以适应不同的场合，并支持各种化妆技巧。它们与粉底完美兼容，助您打造理想的妆容。无论是犒劳自己，还是馈赠挚爱，它们都是您的完美之选。 这套餐具由工匠精心打造，品质卓越。它经久耐用，越用越美丽。无论是特殊场合还是日常使用，它都是理想之选。 不妨用YT-S-5来发现全新的自己，让你的妆容更加与众不同。我们将帮助你享受更愉悦的化妆时光。 * 建议轻柔护理并定期清洁。",
